struct Step{const wchar_t* path;Bytes before,after;};
std::vector<Step> plan(unsigned mode){switch(mode){case 0:return{{L"owned.bin",{},"new"},{L"created.bin",{},"created"}};case 1:return{{L"owned.bin","old","new"},{L"created.bin",{},"created"},{L"obsolete.bin","obsolete",{}}};case 2:return{{L"owned.bin",{},"old"},{L"obsolete.bin","obsolete","obsolete"}};case 3:return{{L"owned.bin","old",{}},{L"obsolete.bin","obsolete",{}}};default:throw std::runtime_error("fixture mode");}}
