int child(HANDLE anchor,int fault){std::array<wchar_t,32768> exe{};need(GetModuleFileNameW(nullptr,exe.data(),static_cast<DWORD>(exe.size()))!=0,"own exe");std::wstring cmd=L"\""+std::wstring(exe.data())+L"\" --fixture-child "+std::to_wstring(reinterpret_cast<uintptr_t>(anchor))+L" "+std::to_wstring(fault);STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};need(CreateProcessW(exe.data(),cmd.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW,nullptr,nullptr,&si,&pi)!=0,"fixture child");Handle process(pi.hProcess),thread(pi.hThread);if(WaitForSingleObject(process.h,30000)!=WAIT_OBJECT_0){preserveFixture=true;throw std::runtime_error("child timeout; preserve fixture; no force stop");}DWORD code{};need(GetExitCodeProcess(process.h,&code)!=0,"child exit");return static_cast<int>(code);}
